from flask import Flask, jsonify, request
import asyncio
import sys
sys.path.insert(0, '/root')
from extract_childcarecrm_fixed4 import CodeNinjasCalendarExtractor

app = Flask(__name__)

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'healthy'}), 200

@app.route('/extract-calendar', methods=['POST', 'GET'])
def extract_calendar():
    try:
        if request.method == 'POST':
            data = request.get_json() or {}
        else:
            data = {}

        calendar_url = data.get('calendar_url', 'https://www.codeninjas.com/east-gwillimbury-on-ca/schedule-tour')
        location_id = data.get('location_id', 'EG')

        extractor = CodeNinjasCalendarExtractor(calendar_url, location_id)
        result = asyncio.run(extractor.extract_all_weeks())

        return jsonify(result), 200

    except Exception as e:
        return jsonify({'error': str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5001, debug=False)

