/**
 * Skyvern booking trigger integration
 * Triggers browser automation to book tours on the calendar
 * Ported from End Of Call - Multicentre n8n workflow
 */

import type { Env } from '../lib/types';

export interface SkyvernBookingPayload {
  action: 'book_tour';
  lead_id: string;
  centre_id: string;
  first_name: string;
  last_name: string;
  phone: string;
  email: string;
  selected_slot: string;
  call_summary: string;
  tour_date?: string;
  tour_time?: string;
  child_name?: string;
  child_birth_year?: number;
}

export interface DateValidationResult {
  valid_date: boolean;
  reason: string;
  parsed_date: string | null;
  original: string;
}

/**
 * Validates a tour date string
 * Ported from End Of Call - Multicentre deterministic validation
 */
export function validateTourDate(dateStr: string | undefined | null): DateValidationResult {
  if (!dateStr || dateStr.toString().trim() === '') {
    return { valid_date: false, reason: 'empty', parsed_date: null, original: dateStr || '' };
  }

  const input = dateStr.toString().trim().toLowerCase();
  const original = dateStr;

  // Month names and abbreviations
  const months = [
    'january', 'february', 'march', 'april', 'may', 'june',
    'july', 'august', 'september', 'october', 'november', 'december',
    'jan', 'feb', 'mar', 'apr', 'jun', 'jul', 'aug', 'sep', 'sept', 'oct', 'nov', 'dec'
  ];

  // Day names (alone are NOT valid)
  const dayNames = [
    'monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday',
    'mon', 'tue', 'wed', 'thu', 'fri', 'sat', 'sun'
  ];

  // Invalid vague terms
  const vagueTerms = ['soon', 'later', 'next week', 'sometime', 'asap', 'whenever', 'tbd', 'not sure'];

  // Check for vague terms
  for (const term of vagueTerms) {
    if (input === term || input.includes(term)) {
      return { valid_date: false, reason: 'vague_term', parsed_date: null, original };
    }
  }

  // Check if it's ONLY a day name (invalid)
  for (const day of dayNames) {
    if (input === day) {
      return { valid_date: false, reason: 'day_only', parsed_date: null, original };
    }
  }

  // Pattern 1: Month name + day number (e.g., "November 28", "Nov 28th")
  const monthDayPattern = new RegExp(`(${months.join('|')})\\s+(\\d{1,2})(?:st|nd|rd|th)?`, 'i');
  if (input.match(monthDayPattern)) {
    return { valid_date: true, reason: 'month_day_format', parsed_date: dateStr, original };
  }

  // Pattern 2: Day number + month name (e.g., "28 November", "28th of November")
  const dayMonthPattern = new RegExp(`(\\d{1,2})(?:st|nd|rd|th)?\\s+(?:of\\s+)?(${months.join('|')})`, 'i');
  if (input.match(dayMonthPattern)) {
    return { valid_date: true, reason: 'day_month_format', parsed_date: dateStr, original };
  }

  // Pattern 3: Numeric dates (e.g., "12/25", "12-25", "12/25/2024")
  const numericPattern = /^(\d{1,2})[\/\-](\d{1,2})(?:[\/\-](\d{2,4}))?$/;
  const numericMatch = input.match(numericPattern);
  if (numericMatch) {
    const month = parseInt(numericMatch[1]);
    const day = parseInt(numericMatch[2]);
    if (month >= 1 && month <= 12 && day >= 1 && day <= 31) {
      return { valid_date: true, reason: 'numeric_format', parsed_date: dateStr, original };
    }
  }

  // Pattern 4: ISO format (e.g., "2024-12-25")
  const isoPattern = /^(\d{4})-(\d{2})-(\d{2})$/;
  if (input.match(isoPattern)) {
    return { valid_date: true, reason: 'iso_format', parsed_date: dateStr, original };
  }

  // Pattern 5: Day name + date (e.g., "Saturday, November 28")
  const dayDatePattern = new RegExp(`(?:${dayNames.join('|')})[,\\s]+.*(${months.join('|')})\\s+(\\d{1,2})`, 'i');
  if (input.match(dayDatePattern)) {
    return { valid_date: true, reason: 'day_date_format', parsed_date: dateStr, original };
  }

  return { valid_date: false, reason: 'no_date_found', parsed_date: null, original };
}

/**
 * Triggers Skyvern to process a booking via workflow dispatch API
 * @param env - Worker environment
 * @param payload - Booking data
 * @returns Object with success status and any error details
 */
export async function triggerBooking(
  env: Env,
  payload: SkyvernBookingPayload
): Promise<{ success: boolean; error?: string; task_id?: string }> {
  // Validate tour date if provided
  if (payload.tour_date) {
    const dateValidation = validateTourDate(payload.tour_date);
    if (!dateValidation.valid_date) {
      console.warn(`Invalid tour date for lead ${payload.lead_id}: ${dateValidation.reason}`);
      return {
        success: false,
        error: `Invalid tour date: ${dateValidation.reason} (value: ${dateValidation.original})`,
      };
    }
  }

  // Check for missing tour date/time
  if (!payload.tour_date || !payload.tour_time) {
    console.warn(`Missing tour date/time for lead ${payload.lead_id}`);
    return {
      success: false,
      error: `Missing tour ${!payload.tour_date ? 'date' : 'time'}`,
    };
  }

  // Use Skyvern API if configured, otherwise fall back to webhook
  if (env.SKYVERN_API_KEY && env.SKYVERN_API_URL) {
    return await triggerSkyvernAPI(env, payload);
  } else if (env.SKYVERN_WEBHOOK_URL) {
    return await triggerSkyvernWebhook(env, payload);
  } else {
    console.warn('Neither SKYVERN_API_KEY nor SKYVERN_WEBHOOK_URL configured');
    return { success: false, error: 'Skyvern not configured' };
  }
}

/**
 * Triggers Skyvern via the workflow dispatch API (preferred method)
 */
async function triggerSkyvernAPI(
  env: Env,
  payload: SkyvernBookingPayload
): Promise<{ success: boolean; error?: string; task_id?: string }> {
  const SKYVERN_WORKFLOW_ID = 'wpid_472637885728525632'; // Code Ninjas tour booking workflow

  try {
    // Correct endpoint: POST /v1/run/workflows with workflow_id in body
    const response = await fetch(`${env.SKYVERN_API_URL}/v1/run/workflows`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': env.SKYVERN_API_KEY!,
      },
      body: JSON.stringify({
        workflow_id: SKYVERN_WORKFLOW_ID,
        // Use 'parameters' not 'data' - this overrides workflow defaults
        parameters: {
          contact_name: `${payload.first_name} ${payload.last_name}`.trim(),
          target_date: payload.tour_date,
          target_time: payload.tour_time,
          child_name: payload.child_name || payload.first_name,
          contact_phone: payload.phone,
          contact_email: payload.email,
          schedule_url: `https://www.codeninjas.com/${payload.centre_id}/schedule-tour`,
          child_birth_year: payload.child_birth_year?.toString() || '',
        },
        webhook_url: `${env.WORKER_URL}/webhook/skyvern`,
        proxy_location: 'RESIDENTIAL',
      }),
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error('Skyvern API error:', response.status, errorText);
      return { success: false, error: `Skyvern API error: ${response.status}` };
    }

    const result = await response.json() as { workflow_run_id?: string };
    console.log('Skyvern workflow dispatched for lead:', payload.lead_id, 'task:', result.workflow_run_id);

    return {
      success: true,
      task_id: result.workflow_run_id,
    };
  } catch (error) {
    console.error('Error calling Skyvern API:', error);
    return { success: false, error: String(error) };
  }
}

/**
 * Triggers Skyvern via simple webhook (fallback method)
 */
async function triggerSkyvernWebhook(
  env: Env,
  payload: SkyvernBookingPayload
): Promise<{ success: boolean; error?: string }> {
  try {
    const response = await fetch(env.SKYVERN_WEBHOOK_URL!, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
      },
      body: JSON.stringify(payload),
    });

    if (!response.ok) {
      const errorText = await response.text();
      console.error('Skyvern webhook error:', response.status, errorText);
      return { success: false, error: `Webhook error: ${response.status}` };
    }

    console.log('Skyvern booking triggered via webhook for lead:', payload.lead_id);
    return { success: true };
  } catch (error) {
    console.error('Error triggering Skyvern webhook:', error);
    return { success: false, error: String(error) };
  }
}

