     1→/**
     2→ * Moltbot + Cloudflare Sandbox
     3→ *
     4→ * This Worker runs Moltbot personal AI assistant in a Cloudflare Sandbox container.
     5→ * It proxies all requests to the Moltbot Gateway's web UI and WebSocket endpoint.
     6→ *
     7→ * Features:
     8→ * - Web UI (Control Dashboard + WebChat) at /
     9→ * - WebSocket support for real-time communication
    10→ * - Admin UI at /_admin/ for device management
    11→ * - Configuration via environment secrets
    12→ *
    13→ * Required secrets (set via `wrangler secret put`):
    14→ * - ANTHROPIC_API_KEY: Your Anthropic API key
    15→ *
    16→ * Optional secrets:
    17→ * - MOLTBOT_GATEWAY_TOKEN: Token to protect gateway access
    18→ * - TELEGRAM_BOT_TOKEN: Telegram bot token
    19→ * - DISCORD_BOT_TOKEN: Discord bot token
    20→ * - SLACK_BOT_TOKEN + SLACK_APP_TOKEN: Slack tokens
    21→ */
    22→
    23→import { Hono } from 'hono';
    24→import { getSandbox, Sandbox, type SandboxOptions } from '@cloudflare/sandbox';
    25→
    26→import type { AppEnv, MoltbotEnv } from './types';
    27→import { MOLTBOT_PORT } from './config';
    28→import { createAccessMiddleware } from './auth';
    29→import { ensureMoltbotGateway, findExistingMoltbotProcess, syncToR2 } from './gateway';
    30→import { publicRoutes, api, adminUi, debug, cdp } from './routes';
    31→import { redactSensitiveParams } from './utils/logging';
    32→import loadingPageHtml from './assets/loading.html';
    33→import configErrorHtml from './assets/config-error.html';
    34→
    35→/**
    36→ * Transform error messages from the gateway to be more user-friendly.
    37→ */
    38→function transformErrorMessage(message: string, host: string): string {
    39→  if (message.includes('gateway token missing') || message.includes('gateway token mismatch')) {
    40→    return `Invalid or missing token. Visit https://${host}?token={REPLACE_WITH_YOUR_TOKEN}`;
    41→  }
    42→
    43→  if (message.includes('pairing required')) {
    44→    return `Pairing required. Visit https://${host}/_admin/`;
    45→  }
    46→
    47→  return message;
    48→}
    49→
    50→export { Sandbox };
    51→
    52→/**
    53→ * Validate required environment variables.
    54→ * Returns an array of missing variable descriptions, or empty array if all are set.
    55→ */
    56→function validateRequiredEnv(env: MoltbotEnv): string[] {
    57→  const missing: string[] = [];
    58→  const isTestMode = env.DEV_MODE === 'true' || env.E2E_TEST_MODE === 'true';
    59→
    60→  if (!env.MOLTBOT_GATEWAY_TOKEN) {
    61→    missing.push('MOLTBOT_GATEWAY_TOKEN');
    62→  }
    63→
    64→  // CF Access vars not required in dev/test mode since auth is skipped
    65→  if (!isTestMode) {
    66→    if (!env.CF_ACCESS_TEAM_DOMAIN) {
    67→      missing.push('CF_ACCESS_TEAM_DOMAIN');
    68→    }
    69→
    70→    if (!env.CF_ACCESS_AUD) {
    71→      missing.push('CF_ACCESS_AUD');
    72→    }
    73→  }
    74→
    75→  // Check for AI Gateway or direct Anthropic configuration
    76→  if (env.AI_GATEWAY_API_KEY) {
    77→    // AI Gateway requires both API key and base URL
    78→    if (!env.AI_GATEWAY_BASE_URL) {
    79→      missing.push('AI_GATEWAY_BASE_URL (required when using AI_GATEWAY_API_KEY)');
    80→    }
    81→  } else if (!env.ANTHROPIC_API_KEY) {
    82→    // Direct Anthropic access requires API key
    83→    missing.push('ANTHROPIC_API_KEY or AI_GATEWAY_API_KEY');
    84→  }
    85→
    86→  return missing;
    87→}
    88→
    89→/**
    90→ * Build sandbox options based on environment configuration.
    91→ * 
    92→ * SANDBOX_SLEEP_AFTER controls how long the container stays alive after inactivity:
    93→ * - 'never' (default): Container stays alive indefinitely (recommended due to long cold starts)
    94→ * - Duration string: e.g., '10m', '1h', '30s' - container sleeps after this period of inactivity
    95→ * 
    96→ * To reduce costs at the expense of cold start latency, set SANDBOX_SLEEP_AFTER to a duration:
    97→ *   npx wrangler secret put SANDBOX_SLEEP_AFTER
    98→ *   # Enter: 10m (or 1h, 30m, etc.)
    99→ */
   100→function buildSandboxOptions(env: MoltbotEnv): SandboxOptions {
   101→  const sleepAfter = env.SANDBOX_SLEEP_AFTER?.toLowerCase() || 'never';
   102→
   103→  // 'never' means keep the container alive indefinitely
   104→  if (sleepAfter === 'never') {
   105→    return { keepAlive: true };
   106→  }
   107→
   108→  // Otherwise, use the specified duration
   109→  return { sleepAfter };
   110→}
   111→
   112→// Main app
   113→const app = new Hono<AppEnv>();
   114→
   115→// =============================================================================
   116→// MIDDLEWARE: Applied to ALL routes
   117→// =============================================================================
   118→
   119→// Middleware: Log every request
   120→app.use('*', async (c, next) => {
   121→  const url = new URL(c.req.url);
   122→  const redactedSearch = redactSensitiveParams(url);
   123→  console.log(`[REQ] ${c.req.method} ${url.pathname}${redactedSearch}`);
   124→  console.log(`[REQ] Has ANTHROPIC_API_KEY: ${!!c.env.ANTHROPIC_API_KEY}`);
   125→  console.log(`[REQ] DEV_MODE: ${c.env.DEV_MODE}`);
   126→  console.log(`[REQ] DEBUG_ROUTES: ${c.env.DEBUG_ROUTES}`);
   127→  await next();
   128→});
   129→
   130→// Middleware: Initialize sandbox for all requests
   131→app.use('*', async (c, next) => {
   132→  const options = buildSandboxOptions(c.env);
   133→  const sandbox = getSandbox(c.env.Sandbox, 'moltbot', options);
   134→  c.set('sandbox', sandbox);
   135→  await next();
   136→});
   137→
   138→// =============================================================================
   139→// PUBLIC ROUTES: No Cloudflare Access authentication required
   140→// =============================================================================
   141→
   142→// Mount public routes first (before auth middleware)
   143→// Includes: /sandbox-health, /logo.png, /logo-small.png, /api/status, /_admin/assets/*
   144→app.route('/', publicRoutes);
   145→
   146→// Mount CDP routes (uses shared secret auth via query param, not CF Access)
   147→app.route('/cdp', cdp);
   148→
   149→// =============================================================================
   150→// PROTECTED ROUTES: Cloudflare Access authentication required
   151→// =============================================================================
   152→
   153→// Middleware: Validate required environment variables (skip in dev mode and for debug routes)
   154→app.use('*', async (c, next) => {
   155→  const url = new URL(c.req.url);
   156→
   157→  // Skip validation for debug routes (they have their own enable check)
   158→  if (url.pathname.startsWith('/debug')) {
   159→    return next();
   160→  }
   161→
   162→  // Skip validation in dev mode
   163→  if (c.env.DEV_MODE === 'true') {
   164→    return next();
   165→  }
   166→
   167→  const missingVars = validateRequiredEnv(c.env);
   168→  if (missingVars.length > 0) {
   169→    console.error('[CONFIG] Missing required environment variables:', missingVars.join(', '));
   170→
   171→    const acceptsHtml = c.req.header('Accept')?.includes('text/html');
   172→    if (acceptsHtml) {
   173→      // Return a user-friendly HTML error page
   174→      const html = configErrorHtml.replace('{{MISSING_VARS}}', missingVars.join(', '));
   175→      return c.html(html, 503);
   176→    }
   177→
   178→    // Return JSON error for API requests
   179→    return c.json({
   180→      error: 'Configuration error',
   181→      message: 'Required environment variables are not configured',
   182→      missing: missingVars,
   183→      hint: 'Set these using: wrangler secret put <VARIABLE_NAME>',
   184→    }, 503);
   185→  }
   186→
   187→  return next();
   188→});
   189→
   190→// Middleware: Cloudflare Access authentication for protected routes
   191→app.use('*', async (c, next) => {
   192→  const url = new URL(c.req.url);
   193→
   194→  // Skip auth for public routes (these are mounted before this middleware but
   195→  // Hono's wildcard middleware still runs for all routes)
   196→  const publicPaths = [
   197→    '/sandbox-health',
   198→    '/api/status',
   199→    '/debug-public',
   200→    '/logo.png',
   201→    '/logo-small.png',
   202→    '/cdp',
   203→  ];
   204→  if (publicPaths.some(path => url.pathname === path || url.pathname.startsWith(path + '/'))) {
   205→    return next();
   206→  }
   207→  // Also skip for admin assets (needed for login page styling)
   208→  if (url.pathname.startsWith('/_admin/assets/')) {
   209→    return next();
   210→  }
   211→
   212→  // Determine response type based on Accept header
   213→  const acceptsHtml = c.req.header('Accept')?.includes('text/html');
   214→  const middleware = createAccessMiddleware({
   215→    type: acceptsHtml ? 'html' : 'json',
   216→    redirectOnMissing: acceptsHtml
   217→  });
   218→
   219→  return middleware(c, next);
   220→});
   221→
   222→// Mount API routes (protected by Cloudflare Access)
   223→app.route('/api', api);
   224→
   225→// Mount Admin UI routes (protected by Cloudflare Access)
   226→app.route('/_admin', adminUi);
   227→
   228→// Mount debug routes (protected by Cloudflare Access, only when DEBUG_ROUTES is enabled)
   229→app.use('/debug/*', async (c, next) => {
   230→  if (c.env.DEBUG_ROUTES !== 'true') {
   231→    return c.json({ error: 'Debug routes are disabled' }, 404);
   232→  }
   233→  return next();
   234→});
   235→app.route('/debug', debug);
   236→
   237→// =============================================================================
   238→// CATCH-ALL: Proxy to Moltbot gateway
   239→// =============================================================================
   240→
   241→app.all('*', async (c) => {
   242→  const sandbox = c.get('sandbox');
   243→  const request = c.req.raw;
   244→  const url = new URL(request.url);
   245→
   246→  console.log('[PROXY] Handling request:', url.pathname);
   247→
   248→  // Check if gateway is already running
   249→  const existingProcess = await findExistingMoltbotProcess(sandbox);
   250→  const isGatewayReady = existingProcess !== null && existingProcess.status === 'running';
   251→
   252→  // For browser requests (non-WebSocket, non-API), show loading page if gateway isn't ready
   253→  const isWebSocketRequest = request.headers.get('Upgrade')?.toLowerCase() === 'websocket';
   254→  const acceptsHtml = request.headers.get('Accept')?.includes('text/html');
   255→
   256→  if (!isGatewayReady && !isWebSocketRequest && acceptsHtml) {
   257→    console.log('[PROXY] Gateway not ready, serving loading page');
   258→
   259→    // Start the gateway in the background (don't await)
   260→    c.executionCtx.waitUntil(
   261→      ensureMoltbotGateway(sandbox, c.env).catch((err: Error) => {
   262→        console.error('[PROXY] Background gateway start failed:', err);
   263→      })
   264→    );
   265→
   266→    // Return the loading page immediately
   267→    return c.html(loadingPageHtml);
   268→  }
   269→
   270→  // Ensure moltbot is running (this will wait for startup)
   271→  try {
   272→    await ensureMoltbotGateway(sandbox, c.env);
   273→  } catch (error) {
   274→    console.error('[PROXY] Failed to start Moltbot:', error);
   275→    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
   276→
   277→    let hint = 'Check worker logs with: wrangler tail';
   278→    if (!c.env.ANTHROPIC_API_KEY) {
   279→      hint = 'ANTHROPIC_API_KEY is not set. Run: wrangler secret put ANTHROPIC_API_KEY';
   280→    } else if (errorMessage.includes('heap out of memory') || errorMessage.includes('OOM')) {
   281→      hint = 'Gateway ran out of memory. Try again or check for memory leaks.';
   282→    }
   283→
   284→    return c.json({
   285→      error: 'Moltbot gateway failed to start',
   286→      details: errorMessage,
   287→      hint,
   288→    }, 503);
   289→  }
   290→
   291→  // Proxy to Moltbot with WebSocket message interception
   292→  if (isWebSocketRequest) {
